import { HashMap, padLength, predictableRandomInt } from '@placeos/common';
import {
    MOCK_PAGE_SIZE,
    mockId,
    persist,
    registerMockEndpoint,
} from '../session';
import { MOCK_MENU } from './catering.data';
import { MOCK_SPACES } from './spaces.data';
import { MOCK_STAFF } from './users.data';
import {
    MOCK_BUILDINGS,
    MOCK_LEVELS,
    MOCK_ORGS,
    MOCK_REGIONS,
    MOCK_ZONES,
} from './zone.data';

const MOCK_METADATA: HashMap<HashMap> = {
    current: {
        contacts: {
            name: 'contacts',
            description: '',
            details: [
                {
                    id: 'user-1',
                    name: 'Jonathan McFarlane (PlaceOS)',
                    email: 'jon@place.tech',
                    first_name: 'Jonathan',
                    last_name: 'McFarlane',
                },
                {
                    id: 'user-1',
                    name: 'Alex Sorafumo (PlaceOS)',
                    email: 'alex@place.tech',
                    first_name: 'Alex',
                    last_name: 'Sorafumo',
                },
            ],
        },
    },
    'zone-org': {
        concierge_app: {
            name: 'concierge_app',
            description: 'Mock-only concierge settings',
            details: {
                parking: {
                    allow_deleting: true,
                },
            },
        },
    },
};

export const LOCKERS = {};

/** Engine settings documents, for zones and systems */
const MOCK_SETTINGS: HashMap[] = [];

export function registerMockZones() {
    const zone_lists = [
        MOCK_ORGS,
        MOCK_REGIONS,
        MOCK_BUILDINGS,
        MOCK_LEVELS,
        MOCK_ZONES,
    ];
    persist('orgs', MOCK_ORGS);
    persist('regions', MOCK_REGIONS);
    persist('buildings', MOCK_BUILDINGS);
    persist('levels', MOCK_LEVELS);
    persist('zones', MOCK_ZONES);
    persist('metadata', MOCK_METADATA);
    persist('lockers', LOCKERS);
    persist('settings', MOCK_SETTINGS);

    const all_zones = () => zone_lists.flat();

    /** List holding the zone and its index, or throw a 404 */
    const locateZone = (id: string) => {
        for (const list of zone_lists) {
            const index = list.findIndex((zone) => zone.id === id);
            if (index >= 0) return { list, index };
        }
        throw { status: 404, message: `Unable to find zone with id "${id}"` };
    };

    registerMockEndpoint({
        path: '/api/engine/v2/zones',
        method: 'GET',
        page_size: MOCK_PAGE_SIZE,
        callback: (request) => {
            let zones = all_zones();
            const tag_list = `${request.query_params?.tags || ''}`
                .split(' ')
                .filter(Boolean);
            if (tag_list.length) {
                zones = zones.filter((zone) =>
                    tag_list.some((tag) => zone.tags.includes(tag)),
                );
            }
            if (request.query_params?.parent_id) {
                zones = zones.filter(
                    (zone) => zone.parent_id === request.query_params.parent_id,
                );
            }
            return zones;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/zones/:id',
        method: 'GET',
        callback: (request) => {
            const zone = all_zones().find(
                (_) => _.id === request.route_params.id,
            );
            if (!zone) {
                throw {
                    status: 404,
                    message: `Unable to find zone with id "${request.route_params.id}"`,
                };
            }
            return zone;
        },
    });

    // New zones go in the generic list. `all_zones` lists every type.
    registerMockEndpoint({
        path: '/api/engine/v2/zones',
        method: 'POST',
        callback: (request) => {
            const zone = { tags: [], ...request.body, id: mockId('zone-') };
            MOCK_ZONES.push(zone);
            return zone;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/zones/:id',
        method: 'PATCH',
        callback: (request) => {
            const { list, index } = locateZone(request.route_params.id);
            const zone = {
                ...list[index],
                ...request.body,
                id: list[index].id,
            };
            list.splice(index, 1, zone);
            return zone;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/zones/:id',
        method: 'DELETE',
        callback: (request) => {
            const { list, index } = locateZone(request.route_params.id);
            list.splice(index, 1);
        },
    });

    const findSettings = (id: string) => {
        const item = MOCK_SETTINGS.find((entry) => entry.id === id);
        if (!item) throw { status: 404, message: 'Settings not found' };
        return item;
    };

    registerMockEndpoint({
        path: '/api/engine/v2/settings',
        method: 'GET',
        callback: (request) => {
            const parent_id = request.query_params?.parent_id;
            return parent_id
                ? MOCK_SETTINGS.filter((item) => item.parent_id === parent_id)
                : MOCK_SETTINGS;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/settings',
        method: 'POST',
        callback: (request) => {
            const item = { ...request.body, id: mockId('sets-') };
            MOCK_SETTINGS.push(item);
            return item;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/settings/:id',
        method: 'GET',
        callback: (request) => findSettings(request.route_params.id),
    });

    registerMockEndpoint({
        path: '/api/engine/v2/settings/:id',
        method: 'PATCH',
        callback: (request) =>
            Object.assign(findSettings(request.route_params.id), request.body),
    });

    /** Metadata of a zone or system, by name. Saved metadata comes first. */
    const showMetadata = (request: {
        route_params: HashMap<string>;
        query_params: HashMap<string>;
    }) => {
        const saved = MOCK_METADATA[request.route_params.id];
        const name = request.query_params.name;
        if (name && saved?.[name]) return { [name]: saved[name] };
        if (request.query_params.name === 'bindings') {
            // Point at a registered mock system, or websocket binds fail
            const system_id = MOCK_SPACES[0].id;
            return {
                bindings: {
                    details: {
                        area_management: system_id,
                        location_services: system_id,
                        contact_tracing: system_id,
                        lockers: system_id,
                        // payments: system_id,
                    },
                },
            };
        }
        if (request.query_params.name === 'catering') {
            return {
                catering: {
                    details: MOCK_MENU,
                },
            };
        }
        if (request.query_params.name === 'catering-settings') {
            return {
                'catering-settings': {
                    details: {
                        require_notes: false,
                        charge_codes: [
                            'CC-1001',
                            'CC-1002',
                            'CC-1003',
                            'CC-2001',
                            'CC-2002',
                        ],
                        disabled_rooms: [],
                    },
                },
            };
        }
        if (request.query_params.name === 'catering_config') {
            return {
                catering_config: {
                    details: [],
                },
            };
        }
        if (request.query_params.name === 'lockers') {
            const parts = request.route_params.id.split('-');
            const id = parts[parts.length - 1];
            return generateLockers(id);
        }
        if (request.query_params.name === 'desks') {
            const parts = request.route_params.id.split('-');
            const id = parts[parts.length - 1];
            return generateMockDeskMetadata(id);
        }
        if (request.query_params.name === 'charge_codes') {
            return {
                charge_codes: {
                    details: new Array(30).fill(0).map((_, idx) => `C-${idx}`),
                },
            };
        }
        if (request.query_params.name === 'map_regions') {
            return {
                map_regions: {
                    details: {
                        areas: [
                            {
                                id: 'zone-10.A',
                                properties: {
                                    capacity: 100,
                                    label_location: { x: 0.36, y: 0.33 },
                                    // draw_polygon: true
                                },
                                geometry: {
                                    coordinates: [
                                        [0.0, 0.0],
                                        [0.0, 0.5],
                                        [0.5, 0.5],
                                        [0.5, 0.0],
                                    ],
                                },
                            },
                            {
                                id: 'zone-10.B',
                                properties: {
                                    capacity: 100,
                                    label_location: { x: 0.76, y: 0.33 },
                                },
                            },
                            {
                                id: 'zone-10.C',
                                properties: {
                                    capacity: 100,
                                    label_location: { x: 0.63, y: 0.77 },
                                },
                            },
                        ],
                    },
                },
            };
        }
        if (
            MOCK_METADATA[request.route_params.id] &&
            MOCK_METADATA[request.route_params.id][request.query_params.name]
        ) {
            return MOCK_METADATA[request.route_params.id];
        } else if (
            MOCK_METADATA[request.route_params.id] &&
            !request.query_params.name
        ) {
            return MOCK_METADATA[request.route_params.id] || {};
        }
        return {};
    };

    registerMockEndpoint({
        path: '/api/engine/v2/metadata/:id',
        method: 'GET',
        callback: (request) => showMetadata(request),
    });

    // The segment after `metadata` is the metadata name here, not an ID
    registerMockEndpoint({
        path: '/api/engine/v2/metadata/:name/bulk',
        method: 'GET',
        callback: (request) => {
            const name = request.route_params.name;
            const ids = `${request.query_params.parent_ids || ''}`
                .split(',')
                .filter(Boolean);
            const result: HashMap = {};
            for (const id of ids) {
                const item = showMetadata({
                    route_params: { id },
                    query_params: { name },
                })[name];
                if (item) result[id] = item;
            }
            return result;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/metadata/:id',
        method: 'PATCH',
        callback: (request) => {
            if (!MOCK_METADATA[request.route_params.id])
                MOCK_METADATA[request.route_params.id] = {};
            MOCK_METADATA[request.route_params.id][request.body.name] =
                request.body;
            return request.body;
        },
    });

    registerMockEndpoint({
        path: '/api/engine/v2/metadata/:id',
        method: 'PUT',
        callback: (request) => {
            if (!MOCK_METADATA[request.route_params.id])
                MOCK_METADATA[request.route_params.id] = {};
            MOCK_METADATA[request.route_params.id][request.body.name] =
                request.body;
            return request.body;
        },
    });

    const DESK_FEATURES = ['sit_to_stand', 'single_monitor', 'dual_monitor'];

    function generateMockDeskMetadata(id: string) {
        return {
            desks: {
                details: new Array(30).fill(0).map((_, idx) => ({
                    id: `table-${padLength(id, 2)}.${padLength(idx + 1, 3)}`,
                    name: `Desk ${id}.${padLength(idx + 1, 3)}`,
                    bookable: predictableRandomInt(9999) % 4 !== 0,
                    groups:
                        predictableRandomInt(9999) % 4 === 0 ? ['test-1'] : [],
                    features: DESK_FEATURES.filter(
                        (_) => predictableRandomInt(99999) % 3 === 0,
                    ),
                })),
            },
        };
    }

    function generateLockers(id: string) {
        if (!LOCKERS[id]) {
            LOCKERS[id] = {
                lockers: {
                    details: new Array(6).fill(0).map((_, idx) => {
                        const position = padLength(idx + 1, 2);
                        const assignee =
                            predictableRandomInt(9999) % 4 === 0
                                ? MOCK_STAFF[
                                      predictableRandomInt(MOCK_STAFF.length)
                                  ]
                                : ({} as any);
                        return {
                            id: `locker-bank-${id}.${position}`,
                            map_id: `bank-${id}.${position}`,
                            level_id: `lvl-02`,
                            name: `Bank ${position}`,
                            height: 3,
                            lockers: new Array(18).fill(0).map((_, idx2) => ({
                                id: `locker-${position}.${padLength(
                                    idx2 + 1,
                                    3,
                                )}`,
                                name: `Locker ${idx2 + 1}`,
                                accessible:
                                    predictableRandomInt(9999) % 2 !== 0,
                                bookable: predictableRandomInt(9999) % 4 !== 0,
                                position: [idx2 % 6, Math.floor(idx2 / 6)],
                                size: [1, 1],
                            })),
                        };
                    }),
                },
            };
        }
        return LOCKERS[id];
    }

    registerMockEndpoint({
        path: '/api/engine/v2/metadata/:id/children',
        method: 'GET',
        callback: (request) => {
            const zone = MOCK_BUILDINGS.find(
                (_) => _.id === request.route_params.id,
            );
            if (!zone)
                throw {
                    status: 404,
                    message: `Unable to find zone with id "${request.route_params.id}"`,
                };
            return MOCK_LEVELS.filter((_) => _.parent_id === zone.id).map(
                (lvl) => {
                    const parts = lvl.id.split('-');
                    const id = parts[parts.length - 1];
                    return {
                        zone: lvl,
                        metadata:
                            request.query_params.name === 'lockers'
                                ? generateLockers(id)
                                : generateMockDeskMetadata(id),
                    };
                },
            );
        },
    });
}
